import React, { useState } from 'react';

function Header({ currentPage, onNavigate, simBalance, userLevel, vipLevel, isUserLoggedIn, username }) {
  const [clickCount, setClickCount] = useState(0);
  const [clickTimer, setClickTimer] = useState(null);

  const menuItems = [
    { id: 'home', icon: '🏠', label: 'خانه' },
    { id: 'wallet', icon: '💳', label: 'کیف پول' },
    { id: 'missions', icon: '📋', label: 'ماموریت' },
    { id: 'profile', icon: '👤', label: 'پروفایل' },
    { id: 'vip', icon: '💎', label: 'VIP' },
    { id: 'referral', icon: '👥', label: 'دعوت' },
    { id: 'about', icon: 'ℹ️', label: 'درباره ما' },
    { id: 'support', icon: '🎫', label: 'پشتیبانی' },
    { id: 'settings', icon: '⚙️', label: 'تنظیمات' }
  ];

  // اگر کاربر وارد شده باشد، پنل کاربری اضافه می‌شود
  if (isUserLoggedIn) {
    menuItems.splice(6, 0, { id: 'userpanel', icon: '👤', label: 'پنل کاربری' });
  }

  // 🔒 لینک مخفی: ۵ بار کلیک روی لوگو
  const handleLogoClick = () => {
    const newCount = clickCount + 1;
    setClickCount(newCount);

    if (clickTimer) {
      clearTimeout(clickTimer);
    }

    if (newCount >= 5) {
      setClickCount(0);
      onNavigate('admin');
      return;
    }

    const timer = setTimeout(() => {
      setClickCount(0);
    }, 2000);
    setClickTimer(timer);
  };

  return (
    <header className="bg-white/80 backdrop-blur-xl border-b border-blue-100/50 sticky top-0 z-20 shadow-sm">
      <div className="flex items-center justify-between p-3 max-w-7xl mx-auto">
        <div 
          className="flex items-center gap-2 cursor-pointer select-none"
          onClick={handleLogoClick}
          title="برای ورود به پنل ادمین ۵ بار کلیک کنید"
        >
          <span className="text-2xl font-bold text-blue-600">⛏️</span>
          <span className="font-bold text-gray-800 text-lg">Coin Mining</span>
        </div>
        <div className="flex gap-1 overflow-x-auto">
          {menuItems.map((item) => (
            <button
              key={item.id}
              onClick={() => onNavigate(item.id)}
              className={`p-2 rounded-xl transition-all text-sm whitespace-nowrap ${
                currentPage === item.id
                  ? 'bg-blue-500/10 text-blue-600 font-medium'
                  : 'hover:bg-gray-100 text-gray-600 hover:text-gray-800'
              }`}
            >
              <span className="text-lg">{item.icon}</span>
              <span className="hidden sm:inline ml-1">{item.label}</span>
            </button>
          ))}
        </div>
      </div>
      <div className="flex justify-between px-3 pb-2 text-xs text-gray-500 max-w-7xl mx-auto">
        <div className="flex gap-4">
          <span>سطح: <span className="font-bold text-gray-700">{userLevel}</span></span>
          <span>VIP: <span className="font-bold text-blue-600">{vipLevel}</span></span>
        </div>
        <div className="flex gap-4">
          {isUserLoggedIn && (
            <span className="text-green-600 font-medium">👤 {username}</span>
          )}
          <span className="font-bold text-blue-600">{simBalance.toFixed(2)} TON</span>
        </div>
      </div>
    </header>
  );
}

export default Header;
